var MELT=[
 ['水 / 冰',0],['汞（水银）',-38.8],['干冰（二氧化碳）',-78.5],['石蜡',64],
 ['锡',231.9],['铅',327.5],['锌',419.5],['镁',650],['铝',660.3],
 ['盐（氯化钠）',801],['银',961.8],['金',1064.2],['铜',1085],['镍',1455],
 ['硅',1414],['铁',1538],['铂',1768],['钛',1668],['钨',3422],['金刚石（碳）',3550]
];
function melting(name){
  if(!name) return {error:'请输入物质名称'};
  var q=String(name).trim();
  for(var i=0;i<MELT.length;i++){ if(MELT[i][0].indexOf(q)>=0||q.indexOf(MELT[i][0])>=0) return {name:MELT[i][0], c:MELT[i][1], f:Math.round(MELT[i][1]*9/5+32)}; }
  return {error:'未收录该物质（可试：水/铁/铜/金/铝/钨/盐…）'};
}
function meltingAll(){ return MELT.map(function(x){return {name:x[0], c:x[1]};}); }
var EXPORTS={melting:melting, meltingAll:meltingAll};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.MeltingPointForgePure = EXPORTS; }
